insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('58698cf1-b2ae-45f0-a0e8-603d56523427', 'heavyweight-cotton-tee-mte002', 'Heavyweight Cotton Tee', 'Cut for a modern, versatile wardrobe, the Heavyweight Cotton Tee moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from cotton blend, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MTE-002', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000011', ARRAY['limited']::text[], 'Heavyweight Cotton Tee | X-Rare', 'Cut for a modern, versatile wardrobe, the Heavyweight Cotton Tee moves easily from day to night. Tailored through the waist and hip for a fit that reads po', now());
