insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('767a18c6-345e-4980-98a5-f16bc210cb30', 'relaxed-fit-pocket-tee-mte003', 'Relaxed Fit Pocket Tee', 'Designed with intention, the Relaxed Fit Pocket Tee balances clean lines with real wearability. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from slub cotton, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MTE-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000011', ARRAY['relaxed','limited']::text[], 'Relaxed Fit Pocket Tee | X-Rare', 'Designed with intention, the Relaxed Fit Pocket Tee balances clean lines with real wearability. A true-to-size cut keeps the silhouette clean and considere', now());
