insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('c842a10a-12f7-470e-9db3-beb055250d51', 'ribbed-crew-tee-mte004', 'Ribbed Crew Tee', 'Cut for a modern, versatile wardrobe, the Ribbed Crew Tee moves easily from day to night. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from pima cotton, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold with like colors; tumble dry low.', 'XR-MTE-004', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000011', ARRAY[]::text[], 'Ribbed Crew Tee | X-Rare', 'Cut for a modern, versatile wardrobe, the Ribbed Crew Tee moves easily from day to night. An oversized cut through the body gives room to move while keepin', now());
