insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('8868a4ae-5c65-4d7b-9a9d-7ce6dc0569f5', 'washed-vintage-tee-mte005', 'Washed Vintage Tee', 'The Washed Vintage Tee brings a considered, easy confidence to everyday dressing. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from organic cotton, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-MTE-005', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000011', ARRAY[]::text[], 'Washed Vintage Tee | X-Rare', 'The Washed Vintage Tee brings a considered, easy confidence to everyday dressing. Tailored through the waist and hip for a fit that reads polished rather t', now());
