insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('a38055de-dba3-4d14-885a-0c79b470b734', 'textured-waffle-knit-tee-mte008', 'Textured Waffle Knit Tee', 'Designed with intention, the Textured Waffle Knit Tee balances clean lines with real wearability. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from slub cotton, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-MTE-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000011', ARRAY[]::text[], 'Textured Waffle Knit Tee | X-Rare', 'Designed with intention, the Textured Waffle Knit Tee balances clean lines with real wearability. A true-to-size cut keeps the silhouette clean and conside', now());
