insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('368b8556-5191-4cb3-83ca-f9ffc6626486', 'long-sleeve-essential-tee-mte010', 'Long Sleeve Essential Tee', 'The Long Sleeve Essential Tee takes a familiar silhouette and refines it with careful proportions. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from organic cotton, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MTE-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000011', ARRAY['essential']::text[], 'Long Sleeve Essential Tee | X-Rare', 'The Long Sleeve Essential Tee takes a familiar silhouette and refines it with careful proportions. An oversized cut through the body gives room to move whi', now());
