insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('d8ba7aac-4040-43b4-bb85-e7ac1832fe6a', 'slub-cotton-tee-mte014', 'Slub Cotton Tee', 'Cut for a modern, versatile wardrobe, the Slub Cotton Tee moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from pima cotton, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-MTE-014', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000011', ARRAY['sale']::text[], 'Slub Cotton Tee | X-Rare', 'Cut for a modern, versatile wardrobe, the Slub Cotton Tee moves easily from day to night. Tailored through the waist and hip for a fit that reads polished ', now());
