insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('7b06ac3b-eed2-45aa-9ce1-58a8909f7372', 'curved-hem-tee-mte015', 'Curved Hem Tee', 'A staple built to be worn often, the Curved Hem Tee pairs effortlessly with the rest of your rotation. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from organic cotton, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold with like colors; tumble dry low.', 'XR-MTE-015', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000011', ARRAY[]::text[], 'Curved Hem Tee | X-Rare', 'A staple built to be worn often, the Curved Hem Tee pairs effortlessly with the rest of your rotation. Tailored through the waist and hip for a fit that re', now());
