insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('df7d5faa-7d0f-4bcb-8e23-8aa647cd14b1', 'baggy-wide-leg-denim-mdn003', 'Baggy Wide Leg Denim', 'The Baggy Wide Leg Denim brings a considered, easy confidence to everyday dressing. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from rigid denim, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. A dependable piece for regular wear, built to outlast a single season. Machine wash cold, hang to dry.', 'XR-MDN-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000012', ARRAY['limited']::text[], 'Baggy Wide Leg Denim | X-Rare', 'The Baggy Wide Leg Denim brings a considered, easy confidence to everyday dressing. A true-to-size cut keeps the silhouette clean and considered, never bul', now());
