insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('e8e91627-7f2c-4938-88b7-258a0a125d26', 'carpenter-denim-mdn008', 'Carpenter Denim', 'Cut for a modern, versatile wardrobe, the Carpenter Denim moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from selvedge denim, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Layer it into a full look or let it stand on its own; either way it holds its shape. Machine wash cold with like colors; tumble dry low.', 'XR-MDN-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000012', ARRAY['sale']::text[], 'Carpenter Denim | X-Rare', 'Cut for a modern, versatile wardrobe, the Carpenter Denim moves easily from day to night. Tailored through the waist and hip for a fit that reads polished ', now());
