insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('e8e247f1-4a14-4d17-837b-d3a4065c2e5f', 'quilted-puffer-jacket-mjk003', 'Quilted Puffer Jacket', 'Cut for a modern, versatile wardrobe, the Quilted Puffer Jacket moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from leather, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MJK-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY[]::text[], 'Quilted Puffer Jacket | X-Rare', 'Cut for a modern, versatile wardrobe, the Quilted Puffer Jacket moves easily from day to night. The fit is relaxed through the body without feeling oversiz', now());
