insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('d040e3f1-bd19-4e67-ab75-5e306346be13', 'varsity-jacket-mjk004', 'Varsity Jacket', 'A staple built to be worn often, the Varsity Jacket pairs effortlessly with the rest of your rotation. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from corduroy, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold, hang to dry.', 'XR-MJK-004', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY[]::text[], 'Varsity Jacket | X-Rare', 'A staple built to be worn often, the Varsity Jacket pairs effortlessly with the rest of your rotation. Tailored through the waist and hip for a fit that re', now());
