insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('17aaa46a-9276-475f-bead-985e7cd20fdc', 'harrington-jacket-mjk005', 'Harrington Jacket', 'The Harrington Jacket brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from quilted nylon, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold with like colors; tumble dry low.', 'XR-MJK-005', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY[]::text[], 'Harrington Jacket | X-Rare', 'The Harrington Jacket brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unfo', now());
