insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('c95accd6-61ee-4dcc-86b2-eb410427f1f0', 'leather-biker-jacket-mjk007', 'Leather Biker Jacket', 'A staple built to be worn often, the Leather Biker Jacket pairs effortlessly with the rest of your rotation. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from nylon, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Wear it as the foundation of an everyday look or dress it up for something more considered. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MJK-007', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY['sale','limited']::text[], 'Leather Biker Jacket | X-Rare', 'A staple built to be worn often, the Leather Biker Jacket pairs effortlessly with the rest of your rotation. The fit is relaxed through the body without fe', now());
