insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('2b53f59f-fd50-4a15-ae31-a976e0de66aa', 'windbreaker-shell-jacket-mjk008', 'Windbreaker Shell Jacket', 'The Windbreaker Shell Jacket takes a familiar silhouette and refines it with careful proportions. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from cotton twill, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MJK-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY['limited']::text[], 'Windbreaker Shell Jacket | X-Rare', 'The Windbreaker Shell Jacket takes a familiar silhouette and refines it with careful proportions. An oversized cut through the body gives room to move whil', now());
