insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('e4f718d1-5cb0-4131-8ea9-90421722578c', 'corduroy-overshirt-jacket-mjk009', 'Corduroy Overshirt Jacket', 'Designed with intention, the Corduroy Overshirt Jacket balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from leather, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MJK-009', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY[]::text[], 'Corduroy Overshirt Jacket | X-Rare', 'Designed with intention, the Corduroy Overshirt Jacket balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads ', now());
