insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('eebb7320-505b-46b7-827a-8662ac8e2771', 'fleece-lined-jacket-mjk010', 'Fleece-Lined Jacket', 'The Fleece-Lined Jacket brings a considered, easy confidence to everyday dressing. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from corduroy, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. It''s built for rotation — as comfortable running errands as it is out for the evening. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MJK-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY[]::text[], 'Fleece-Lined Jacket | X-Rare', 'The Fleece-Lined Jacket brings a considered, easy confidence to everyday dressing. A true-to-size cut keeps the silhouette clean and considered, never bulk', now());
