insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('0263e80a-d65e-43fd-865d-82b37bfaaa2a', 'utility-work-jacket-mjk011', 'Utility Work Jacket', 'Cut for a modern, versatile wardrobe, the Utility Work Jacket moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from quilted nylon, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-MJK-011', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY[]::text[], 'Utility Work Jacket | X-Rare', 'Cut for a modern, versatile wardrobe, the Utility Work Jacket moves easily from day to night. The fit is relaxed through the body without feeling oversized', now());
