insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('6a98de6b-08db-4a2b-930e-d646c75bfde5', 'shearling-collar-jacket-mjk013', 'Shearling Collar Jacket', 'Cut for a modern, versatile wardrobe, the Shearling Collar Jacket moves easily from day to night. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from nylon, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MJK-013', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000013', ARRAY[]::text[], 'Shearling Collar Jacket | X-Rare', 'Cut for a modern, versatile wardrobe, the Shearling Collar Jacket moves easily from day to night. A true-to-size cut keeps the silhouette clean and conside', now());
