insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('959a4440-2ba2-4b34-8dfa-2d14204f5951', 'cropped-hoodie-mhd006', 'Cropped Hoodie', 'Designed with intention, the Cropped Hoodie balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from brushed fleece, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Layer it into a full look or let it stand on its own; either way it holds its shape. Machine wash cold, hang to dry.', 'XR-MHD-006', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear','sale']::text[], 'Cropped Hoodie | X-Rare', 'Designed with intention, the Cropped Hoodie balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, so i', now());
