insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('01a44d97-9243-410e-8f62-a08f5f6795ca', 'tie-dye-hoodie-mhd007', 'Tie-Dye Hoodie', 'Cut for a modern, versatile wardrobe, the Tie-Dye Hoodie moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from cotton blend, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MHD-007', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear']::text[], 'Tie-Dye Hoodie | X-Rare', 'Cut for a modern, versatile wardrobe, the Tie-Dye Hoodie moves easily from day to night. The fit is relaxed through the body without feeling oversized, so ', now());
