insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('d71197ee-ad2b-483e-a7c0-d2f966f51519', 'colorblock-hoodie-mhd008', 'Colorblock Hoodie', 'Cut for a modern, versatile wardrobe, the Colorblock Hoodie moves easily from day to night. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from french terry, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. Wear it as the foundation of an everyday look or dress it up for something more considered. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MHD-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear']::text[], 'Colorblock Hoodie | X-Rare', 'Cut for a modern, versatile wardrobe, the Colorblock Hoodie moves easily from day to night. A true-to-size cut keeps the silhouette clean and considered, n', now());
