insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('8be5747f-348b-4353-a4c9-6623b0d62c60', 'graphic-print-hoodie-mhd010', 'Graphic Print Hoodie', 'A staple built to be worn often, the Graphic Print Hoodie pairs effortlessly with the rest of your rotation. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from brushed fleece, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MHD-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear']::text[], 'Graphic Print Hoodie | X-Rare', 'A staple built to be worn often, the Graphic Print Hoodie pairs effortlessly with the rest of your rotation. Tailored through the waist and hip for a fit t', now());
