insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('470cfdc7-d5d8-48cb-b8b9-0d070a2913db', 'sleeveless-hoodie-mhd012', 'Sleeveless Hoodie', 'Designed with intention, the Sleeveless Hoodie balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from french terry, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MHD-012', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear','limited']::text[], 'Sleeveless Hoodie | X-Rare', 'Designed with intention, the Sleeveless Hoodie balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, s', now());
