insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('17755f43-1425-4b69-a9f8-d237aa738733', 'two-tone-hoodie-mhd013', 'Two-Tone Hoodie', 'Cut for a modern, versatile wardrobe, the Two-Tone Hoodie moves easily from day to night. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from cotton fleece, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold, hang to dry.', 'XR-MHD-013', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear','sale','limited']::text[], 'Two-Tone Hoodie | X-Rare', 'Cut for a modern, versatile wardrobe, the Two-Tone Hoodie moves easily from day to night. Cut with a slightly dropped shoulder and a straight body for an e', now());
