insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('d6c37d1d-b859-499a-a10b-bb210dd73836', 'boxy-fit-hoodie-mhd014', 'Boxy Fit Hoodie', 'The Boxy Fit Hoodie takes a familiar silhouette and refines it with careful proportions. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from brushed fleece, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold with like colors; tumble dry low.', 'XR-MHD-014', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear','oversized']::text[], 'Boxy Fit Hoodie | X-Rare', 'The Boxy Fit Hoodie takes a familiar silhouette and refines it with careful proportions. A true-to-size cut keeps the silhouette clean and considered, neve', now());
