insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('0f20369d-24a9-4cd5-adb6-1a75c5f109c9', 'brushed-fleece-hoodie-mhd015', 'Brushed Fleece Hoodie', 'The Brushed Fleece Hoodie takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from cotton blend, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MHD-015', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear']::text[], 'Brushed Fleece Hoodie | X-Rare', 'The Brushed Fleece Hoodie takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversize', now());
