insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('e794f333-486c-4509-8057-ad703c0dfe36', 'essential-pullover-hoodie-mhd018', 'Essential Pullover Hoodie', 'Cut for a modern, versatile wardrobe, the Essential Pullover Hoodie moves easily from day to night. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from brushed fleece, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MHD-018', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000014', ARRAY['streetwear','essential']::text[], 'Essential Pullover Hoodie | X-Rare', 'Cut for a modern, versatile wardrobe, the Essential Pullover Hoodie moves easily from day to night. A true-to-size cut keeps the silhouette clean and consi', now());
