insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('458a5139-1208-4bd9-ba5e-448f5de22760', 'pleated-trouser-mpn004', 'Pleated Trouser', 'A staple built to be worn often, the Pleated Trouser pairs effortlessly with the rest of your rotation. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from corduroy, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. Wear it as the foundation of an everyday look or dress it up for something more considered. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MPN-004', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000031', ARRAY[]::text[], 'Pleated Trouser | X-Rare', 'A staple built to be worn often, the Pleated Trouser pairs effortlessly with the rest of your rotation. An oversized cut through the body gives room to mov', now());
