insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('3bc0b89f-4df4-42c3-a1e7-a5c719153155', 'corduroy-trouser-mpn007', 'Corduroy Trouser', 'Designed with intention, the Corduroy Trouser balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from wool blend, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-MPN-007', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000031', ARRAY[]::text[], 'Corduroy Trouser | X-Rare', 'Designed with intention, the Corduroy Trouser balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads polished ', now());
