insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('e2f193fa-646d-451a-8a4c-d8a4d4127921', 'parachute-cargo-pant-mpn010', 'Parachute Cargo Pant', 'A staple built to be worn often, the Parachute Cargo Pant pairs effortlessly with the rest of your rotation. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from ripstop nylon, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold, hang to dry.', 'XR-MPN-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000031', ARRAY[]::text[], 'Parachute Cargo Pant | X-Rare', 'A staple built to be worn often, the Parachute Cargo Pant pairs effortlessly with the rest of your rotation. An oversized cut through the body gives room t', now());
