insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('18adf5f8-86d3-4b4f-9650-acb2dbfdefef', 'ripstop-cargo-pant-mpn014', 'Ripstop Cargo Pant', 'Cut for a modern, versatile wardrobe, the Ripstop Cargo Pant moves easily from day to night. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from corduroy, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MPN-014', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000031', ARRAY['limited']::text[], 'Ripstop Cargo Pant | X-Rare', 'Cut for a modern, versatile wardrobe, the Ripstop Cargo Pant moves easily from day to night. Cut with a slightly dropped shoulder and a straight body for a', now());
