insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('bee04db6-0014-4a83-b0f6-07e3f3f42d68', 'pinstripe-trouser-mpn015', 'Pinstripe Trouser', 'Cut for a modern, versatile wardrobe, the Pinstripe Trouser moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from ripstop nylon, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold, hang to dry.', 'XR-MPN-015', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000031', ARRAY['limited']::text[], 'Pinstripe Trouser | X-Rare', 'Cut for a modern, versatile wardrobe, the Pinstripe Trouser moves easily from day to night. The fit is relaxed through the body without feeling oversized, ', now());
