insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('2110ef3b-6f51-4716-ae13-d5ee85d7d665', 'classic-zip-tracksuit-mts001', 'Classic Zip Tracksuit', 'Designed with intention, the Classic Zip Tracksuit balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from polyester, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Wear it as the foundation of an everyday look or dress it up for something more considered. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MTS-001', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000032', ARRAY['streetwear','essential','sale']::text[], 'Classic Zip Tracksuit | X-Rare', 'Designed with intention, the Classic Zip Tracksuit balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads poli', now());
