insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('a06ba87d-0772-42f8-b369-4640f8f83e7b', 'colorblock-tracksuit-mts002', 'Colorblock Tracksuit', 'Designed with intention, the Colorblock Tracksuit balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from cotton fleece, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MTS-002', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000032', ARRAY['streetwear']::text[], 'Colorblock Tracksuit | X-Rare', 'Designed with intention, the Colorblock Tracksuit balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads polis', now());
