insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('91198146-1f9b-4d26-acd6-456b782dd979', 'fleece-tracksuit-set-mts003', 'Fleece Tracksuit Set', 'The Fleece Tracksuit Set takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from velour, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold, hang to dry.', 'XR-MTS-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000032', ARRAY['streetwear']::text[], 'Fleece Tracksuit Set | X-Rare', 'The Fleece Tracksuit Set takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized', now());
