insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('60f6ac2a-f072-447f-a399-b1aed282e789', 'retro-stripe-tracksuit-mts005', 'Retro Stripe Tracksuit', 'Designed with intention, the Retro Stripe Tracksuit balances clean lines with real wearability. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from polyester, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Wear it as the foundation of an everyday look or dress it up for something more considered. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MTS-005', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000032', ARRAY['streetwear']::text[], 'Retro Stripe Tracksuit | X-Rare', 'Designed with intention, the Retro Stripe Tracksuit balances clean lines with real wearability. Cut with a slightly dropped shoulder and a straight body fo', now());
