insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('19c1e76b-2cfd-475a-b99d-484c4674a9e7', 'mesh-panel-tracksuit-mts007', 'Mesh Panel Tracksuit', 'The Mesh Panel Tracksuit takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from velour, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold, hang to dry.', 'XR-MTS-007', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000032', ARRAY['streetwear']::text[], 'Mesh Panel Tracksuit | X-Rare', 'The Mesh Panel Tracksuit takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized', now());
