insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('59280973-4666-465b-8317-ae98f174f1ef', 'minimal-logo-tracksuit-mts008', 'Minimal Logo Tracksuit', 'The Minimal Logo Tracksuit takes a familiar silhouette and refines it with careful proportions. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from ribbed knit, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MTS-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000032', ARRAY['streetwear','sale']::text[], 'Minimal Logo Tracksuit | X-Rare', 'The Minimal Logo Tracksuit takes a familiar silhouette and refines it with careful proportions. Cut with a slightly dropped shoulder and a straight body fo', now());
