insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('7d9694fa-3b0b-43be-a6bc-bed9cce3dd41', 'two-tone-tracksuit-mts009', 'Two-Tone Tracksuit', 'The Two-Tone Tracksuit takes a familiar silhouette and refines it with careful proportions. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from polyester, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-MTS-009', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000032', ARRAY['streetwear']::text[], 'Two-Tone Tracksuit | X-Rare', 'The Two-Tone Tracksuit takes a familiar silhouette and refines it with careful proportions. Tailored through the waist and hip for a fit that reads polishe', now());
