insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('0671e414-c63f-4e03-9b09-fbfa8eaeeac9', 'cropped-tracksuit-set-mts010', 'Cropped Tracksuit Set', 'A staple built to be worn often, the Cropped Tracksuit Set pairs effortlessly with the rest of your rotation. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from cotton fleece, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. It''s built for rotation — as comfortable running errands as it is out for the evening. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MTS-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000032', ARRAY['streetwear']::text[], 'Cropped Tracksuit Set | X-Rare', 'A staple built to be worn often, the Cropped Tracksuit Set pairs effortlessly with the rest of your rotation. The fit is relaxed through the body without f', now());
