insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('980427fd-f865-4679-8d8a-fcb395c683c4', 'wool-overcoat-mow001', 'Wool Overcoat', 'Cut for a modern, versatile wardrobe, the Wool Overcoat moves easily from day to night. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from wool blend, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MOW-001', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000033', ARRAY['premium']::text[], 'Wool Overcoat | X-Rare', 'Cut for a modern, versatile wardrobe, the Wool Overcoat moves easily from day to night. A true-to-size cut keeps the silhouette clean and considered, never', now());
