insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('61d73591-2a4e-48fc-8dcd-deddb175f1cd', 'quilted-parka-mow003', 'Quilted Parka', 'The Quilted Parka brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from cotton twill, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold with like colors; tumble dry low.', 'XR-MOW-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000033', ARRAY['premium']::text[], 'Quilted Parka | X-Rare', 'The Quilted Parka brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unforced', now());
