insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('66561097-5743-49b3-94cc-9a759473ae14', 'car-coat-mow007', 'Car Coat', 'Cut for a modern, versatile wardrobe, the Car Coat moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from down fill, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-MOW-007', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000033', ARRAY['premium']::text[], 'Car Coat | X-Rare', 'Cut for a modern, versatile wardrobe, the Car Coat moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it lay', now());
