insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('62dc4c42-38d8-4da9-9513-d38edf7b2b86', 'technical-rain-shell-mow008', 'Technical Rain Shell', 'The Technical Rain Shell brings a considered, easy confidence to everyday dressing. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from cotton twill, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Layer it into a full look or let it stand on its own; either way it holds its shape. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MOW-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000033', ARRAY['premium','limited']::text[], 'Technical Rain Shell | X-Rare', 'The Technical Rain Shell brings a considered, easy confidence to everyday dressing. Tailored through the waist and hip for a fit that reads polished rather', now());
