insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('ced5cf9f-a414-494c-9503-9d24ae98df06', 'belted-wrap-coat-mow009', 'Belted Wrap Coat', 'A staple built to be worn often, the Belted Wrap Coat pairs effortlessly with the rest of your rotation. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from shearling, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. A dependable piece for regular wear, built to outlast a single season. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MOW-009', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000033', ARRAY['premium','limited']::text[], 'Belted Wrap Coat | X-Rare', 'A staple built to be worn often, the Belted Wrap Coat pairs effortlessly with the rest of your rotation. An oversized cut through the body gives room to mo', now());
