insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('efc98ef9-9286-4732-8f7e-8470e3c06000', 'peacoat-mow010', 'Peacoat', 'The Peacoat brings a considered, easy confidence to everyday dressing. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from technical nylon, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MOW-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000033', ARRAY['premium','limited']::text[], 'Peacoat | X-Rare', 'The Peacoat brings a considered, easy confidence to everyday dressing. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from', now());
