insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('682b13b9-7a39-457b-af4e-1c6d3ba7bb5a', 'insulated-field-coat-mow011', 'Insulated Field Coat', 'The Insulated Field Coat brings a considered, easy confidence to everyday dressing. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from wool blend, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Wear it as the foundation of an everyday look or dress it up for something more considered. Hand wash cold and lay flat to dry to keep its finish.', 'XR-MOW-011', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000033', ARRAY['premium']::text[], 'Insulated Field Coat | X-Rare', 'The Insulated Field Coat brings a considered, easy confidence to everyday dressing. The fit is relaxed through the body without feeling oversized, so it la', now());
