insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('bb87b219-7764-46c0-abc6-f9d41fe391e9', 'wool-blend-duffle-coat-mow012', 'Wool Blend Duffle Coat', 'The Wool Blend Duffle Coat brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from down fill, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. A dependable piece for regular wear, built to outlast a single season. Spot clean or dry clean recommended to preserve shape and color.', 'XR-MOW-012', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000033', ARRAY['premium','sale']::text[], 'Wool Blend Duffle Coat | X-Rare', 'The Wool Blend Duffle Coat brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy,', now());
