insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('389907a3-292a-4652-9ce6-b67b97572bc0', 'silk-blend-cami-top-wtp001', 'Silk Blend Cami Top', 'The Silk Blend Cami Top takes a familiar silhouette and refines it with careful proportions. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from satin, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-WTP-001', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Silk Blend Cami Top | X-Rare', 'The Silk Blend Cami Top takes a familiar silhouette and refines it with careful proportions. Tailored through the waist and hip for a fit that reads polish', now());
