insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('baf4b72a-82a3-425e-a691-53b4943f84dd', 'fitted-bodysuit-top-wtp002', 'Fitted Bodysuit Top', 'Cut for a modern, versatile wardrobe, the Fitted Bodysuit Top moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from silk blend, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WTP-002', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY['slim']::text[], 'Fitted Bodysuit Top | X-Rare', 'Cut for a modern, versatile wardrobe, the Fitted Bodysuit Top moves easily from day to night. Tailored through the waist and hip for a fit that reads polis', now());
