insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('d8c6b5f1-39cb-4445-9654-fd436cdb4658', 'off-shoulder-blouse-wtp003', 'Off-Shoulder Blouse', 'Designed with intention, the Off-Shoulder Blouse balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from ribbed knit, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. A dependable piece for regular wear, built to outlast a single season. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WTP-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Off-Shoulder Blouse | X-Rare', 'Designed with intention, the Off-Shoulder Blouse balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized,', now());
