insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('97607fb0-f622-42db-9ca1-a0a6dc079777', 'wrap-front-top-wtp004', 'Wrap Front Top', 'The Wrap Front Top takes a familiar silhouette and refines it with careful proportions. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from linen, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Wear it as the foundation of an everyday look or dress it up for something more considered. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WTP-004', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Wrap Front Top | X-Rare', 'The Wrap Front Top takes a familiar silhouette and refines it with careful proportions. Cut with a slightly dropped shoulder and a straight body for an eas', now());
