insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('95a57983-2f33-4e53-a5db-7e6bb1c57aee', 'cropped-knit-top-wtp005', 'Cropped Knit Top', 'The Cropped Knit Top takes a familiar silhouette and refines it with careful proportions. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from mesh, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. Layer it into a full look or let it stand on its own; either way it holds its shape. Machine wash cold, hang to dry.', 'XR-WTP-005', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Cropped Knit Top | X-Rare', 'The Cropped Knit Top takes a familiar silhouette and refines it with careful proportions. An oversized cut through the body gives room to move while keepin', now());
