insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('2c452e33-7ba2-4a03-8c01-c8d5a4469a19', 'satin-slip-top-wtp007', 'Satin Slip Top', 'A staple built to be worn often, the Satin Slip Top pairs effortlessly with the rest of your rotation. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from satin, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WTP-007', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY['sale']::text[], 'Satin Slip Top | X-Rare', 'A staple built to be worn often, the Satin Slip Top pairs effortlessly with the rest of your rotation. Tailored through the waist and hip for a fit that re', now());
