insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('06acdde8-804d-46b9-973e-254fecfc4497', 'ruched-bodycon-top-wtp008', 'Ruched Bodycon Top', 'The Ruched Bodycon Top takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from silk blend, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Wear it as the foundation of an everyday look or dress it up for something more considered. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WTP-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Ruched Bodycon Top | X-Rare', 'The Ruched Bodycon Top takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized, ', now());
