insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('d3b560e5-b2c3-47ca-b9c2-04786cc77da0', 'halter-neck-top-wtp009', 'Halter Neck Top', 'The Halter Neck Top takes a familiar silhouette and refines it with careful proportions. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from ribbed knit, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WTP-009', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Halter Neck Top | X-Rare', 'The Halter Neck Top takes a familiar silhouette and refines it with careful proportions. An oversized cut through the body gives room to move while keeping', now());
