insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('7d909298-4257-45cc-9aef-3aa8b4c8326d', 'cowl-neck-top-wtp010', 'Cowl Neck Top', 'The Cowl Neck Top brings a considered, easy confidence to everyday dressing. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from linen, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WTP-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Cowl Neck Top | X-Rare', 'The Cowl Neck Top brings a considered, easy confidence to everyday dressing. Tailored through the waist and hip for a fit that reads polished rather than f', now());
