insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('6cc4c1c7-617e-4869-8027-b062faf94235', 'corset-style-top-wtp013', 'Corset Style Top', 'The Corset Style Top takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from satin, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WTP-013', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Corset Style Top | X-Rare', 'The Corset Style Top takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized, so', now());
