insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('19314219-4d7e-4168-bd8e-6ed585e0373c', 'draped-jersey-top-wtp015', 'Draped Jersey Top', 'The Draped Jersey Top takes a familiar silhouette and refines it with careful proportions. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from ribbed knit, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WTP-015', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY[]::text[], 'Draped Jersey Top | X-Rare', 'The Draped Jersey Top takes a familiar silhouette and refines it with careful proportions. Tailored through the waist and hip for a fit that reads polished', now());
