insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('3ec05219-e762-4986-9e84-0038b3b8f04b', 'peplum-top-wtp016', 'Peplum Top', 'A staple built to be worn often, the Peplum Top pairs effortlessly with the rest of your rotation. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from linen, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold with like colors; tumble dry low.', 'XR-WTP-016', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY['limited']::text[], 'Peplum Top | X-Rare', 'A staple built to be worn often, the Peplum Top pairs effortlessly with the rest of your rotation. Cut with a slightly dropped shoulder and a straight body', now());
