insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('18c9484e-61fe-49ec-b2cc-5565b2f49d31', 'sheer-layered-top-wtp017', 'Sheer Layered Top', 'A staple built to be worn often, the Sheer Layered Top pairs effortlessly with the rest of your rotation. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from mesh, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. Layer it into a full look or let it stand on its own; either way it holds its shape. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WTP-017', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000021', ARRAY['limited']::text[], 'Sheer Layered Top | X-Rare', 'A staple built to be worn often, the Sheer Layered Top pairs effortlessly with the rest of your rotation. Cut with a slightly dropped shoulder and a straig', now());
