insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('71bd410c-eddf-400b-9260-17f089c085c0', 'a-line-midi-skirt-wsk003', 'A-Line Midi Skirt', 'Cut for a modern, versatile wardrobe, the A-Line Midi Skirt moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from cotton twill, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold with like colors; tumble dry low.', 'XR-WSK-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000022', ARRAY[]::text[], 'A-Line Midi Skirt | X-Rare', 'Cut for a modern, versatile wardrobe, the A-Line Midi Skirt moves easily from day to night. The fit is relaxed through the body without feeling oversized, ', now());
