insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('07d3f6b8-80c7-4b29-8f66-f4935a67b267', 'ruched-bodycon-skirt-wsk005', 'Ruched Bodycon Skirt', 'The Ruched Bodycon Skirt takes a familiar silhouette and refines it with careful proportions. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from tweed, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Layer it into a full look or let it stand on its own; either way it holds its shape. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WSK-005', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000022', ARRAY[]::text[], 'Ruched Bodycon Skirt | X-Rare', 'The Ruched Bodycon Skirt takes a familiar silhouette and refines it with careful proportions. A true-to-size cut keeps the silhouette clean and considered,', now());
