insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('2fcf8cab-02e0-48c0-9713-e63842e123b1', 'tiered-maxi-skirt-wsk006', 'Tiered Maxi Skirt', 'The Tiered Maxi Skirt brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from ribbed knit, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Wear it as the foundation of an everyday look or dress it up for something more considered. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WSK-006', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000022', ARRAY[]::text[], 'Tiered Maxi Skirt | X-Rare', 'The Tiered Maxi Skirt brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unfo', now());
