insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('1e1bd2dc-fb49-4cd4-8744-dc7236b63f45', 'corduroy-mini-skirt-wsk008', 'Corduroy Mini Skirt', 'Designed with intention, the Corduroy Mini Skirt balances clean lines with real wearability. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from denim, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WSK-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000022', ARRAY['sale']::text[], 'Corduroy Mini Skirt | X-Rare', 'Designed with intention, the Corduroy Mini Skirt balances clean lines with real wearability. An oversized cut through the body gives room to move while kee', now());
