insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('550f19a6-8c11-4962-9aa9-89b2ddabae16', 'slip-style-skirt-wsk009', 'Slip Style Skirt', 'Cut for a modern, versatile wardrobe, the Slip Style Skirt moves easily from day to night. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from cotton twill, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold with like colors; tumble dry low.', 'XR-WSK-009', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000022', ARRAY[]::text[], 'Slip Style Skirt | X-Rare', 'Cut for a modern, versatile wardrobe, the Slip Style Skirt moves easily from day to night. Cut with a slightly dropped shoulder and a straight body for an ', now());
