insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('438c96c8-7594-467e-a633-038f494d6854', 'high-waisted-pencil-skirt-wsk010', 'High-Waisted Pencil Skirt', 'The High-Waisted Pencil Skirt brings a considered, easy confidence to everyday dressing. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from faux leather, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WSK-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000022', ARRAY[]::text[], 'High-Waisted Pencil Skirt | X-Rare', 'The High-Waisted Pencil Skirt brings a considered, easy confidence to everyday dressing. Tailored through the waist and hip for a fit that reads polished r', now());
