insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('4d7e5c0e-fe89-48d6-8820-973a49cf19b6', 'cargo-utility-skirt-wsk011', 'Cargo Utility Skirt', 'The Cargo Utility Skirt takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from tweed, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WSK-011', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000022', ARRAY[]::text[], 'Cargo Utility Skirt | X-Rare', 'The Cargo Utility Skirt takes a familiar silhouette and refines it with careful proportions. The fit is relaxed through the body without feeling oversized,', now());
