insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('5fe5629f-3735-4848-aa1e-eb6e428be33a', 'textured-tweed-skirt-wsk015', 'Textured Tweed Skirt', 'A staple built to be worn often, the Textured Tweed Skirt pairs effortlessly with the rest of your rotation. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from cotton twill, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. Layer it into a full look or let it stand on its own; either way it holds its shape. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WSK-015', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000022', ARRAY['sale']::text[], 'Textured Tweed Skirt | X-Rare', 'A staple built to be worn often, the Textured Tweed Skirt pairs effortlessly with the rest of your rotation. A true-to-size cut keeps the silhouette clean ', now());
