insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('5804017d-cfd6-410a-b3bd-3a7b9d2cd533', 'oversized-boyfriend-hoodie-whd002', 'Oversized Boyfriend Hoodie', 'Cut for a modern, versatile wardrobe, the Oversized Boyfriend Hoodie moves easily from day to night. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from brushed fleece, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. Wear it as the foundation of an everyday look or dress it up for something more considered. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WHD-002', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000035', ARRAY['streetwear','oversized','limited']::text[], 'Oversized Boyfriend Hoodie | X-Rare', 'Cut for a modern, versatile wardrobe, the Oversized Boyfriend Hoodie moves easily from day to night. An oversized cut through the body gives room to move w', now());
