insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('80e14df9-cdbc-404d-bc8a-e2b6f812104d', 'fitted-ribbed-hoodie-whd003', 'Fitted Ribbed Hoodie', 'Designed with intention, the Fitted Ribbed Hoodie balances clean lines with real wearability. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from french terry, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WHD-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000035', ARRAY['streetwear','slim','limited']::text[], 'Fitted Ribbed Hoodie | X-Rare', 'Designed with intention, the Fitted Ribbed Hoodie balances clean lines with real wearability. A true-to-size cut keeps the silhouette clean and considered,', now());
