insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('5b0574d7-390e-4492-a62f-3f186efafd0a', 'tie-front-hoodie-whd004', 'Tie-Front Hoodie', 'Cut for a modern, versatile wardrobe, the Tie-Front Hoodie moves easily from day to night. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from cotton fleece, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. A dependable piece for regular wear, built to outlast a single season. Machine wash cold with like colors; tumble dry low.', 'XR-WHD-004', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000035', ARRAY['streetwear']::text[], 'Tie-Front Hoodie | X-Rare', 'Cut for a modern, versatile wardrobe, the Tie-Front Hoodie moves easily from day to night. A true-to-size cut keeps the silhouette clean and considered, ne', now());
