insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('5404188c-d837-4422-952f-f4b79a266cf2', 'cinched-waist-hoodie-whd010', 'Cinched Waist Hoodie', 'Designed with intention, the Cinched Waist Hoodie balances clean lines with real wearability. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from cotton fleece, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WHD-010', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000035', ARRAY['streetwear']::text[], 'Cinched Waist Hoodie | X-Rare', 'Designed with intention, the Cinched Waist Hoodie balances clean lines with real wearability. A true-to-size cut keeps the silhouette clean and considered,', now());
