insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('47441853-b987-4536-9d3c-4fb2e03c231d', 'layered-hem-hoodie-whd014', 'Layered Hem Hoodie', 'Cut for a modern, versatile wardrobe, the Layered Hem Hoodie moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from brushed fleece, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WHD-014', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000035', ARRAY['streetwear','sale']::text[], 'Layered Hem Hoodie | X-Rare', 'Cut for a modern, versatile wardrobe, the Layered Hem Hoodie moves easily from day to night. Tailored through the waist and hip for a fit that reads polish', now());
