insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('0f6fdba4-9967-444b-abce-49d027dbf80e', 'ribbed-crop-tee-wte003', 'Ribbed Crop Tee', 'Cut for a modern, versatile wardrobe, the Ribbed Crop Tee moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from cotton blend, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Layer it into a full look or let it stand on its own; either way it holds its shape. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WTE-003', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000034', ARRAY[]::text[], 'Ribbed Crop Tee | X-Rare', 'Cut for a modern, versatile wardrobe, the Ribbed Crop Tee moves easily from day to night. Tailored through the waist and hip for a fit that reads polished ', now());
