insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('6f2f7000-0fc1-4b7c-ba37-930e21469c1d', 'cap-sleeve-tee-wte004', 'Cap Sleeve Tee', 'The Cap Sleeve Tee brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from pima cotton, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. A dependable piece for regular wear, built to outlast a single season. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WTE-004', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000034', ARRAY[]::text[], 'Cap Sleeve Tee | X-Rare', 'The Cap Sleeve Tee brings a considered, easy confidence to everyday dressing. Cut with a slightly dropped shoulder and a straight body for an easy, unforce', now());
