insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('5f6c6f90-22c1-4aed-8d9c-9c4d2b49620f', 'scoop-neck-tee-wte009', 'Scoop Neck Tee', 'Designed with intention, the Scoop Neck Tee balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from cotton, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. Layer it into a full look or let it stand on its own; either way it holds its shape. Machine wash cold with like colors; tumble dry low.', 'XR-WTE-009', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000034', ARRAY['limited']::text[], 'Scoop Neck Tee | X-Rare', 'Designed with intention, the Scoop Neck Tee balances clean lines with real wearability. Tailored through the waist and hip for a fit that reads polished ra', now());
