insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('479254fa-3a59-4324-a82f-d03a75cb20ba', 'slub-cotton-tee-wte011', 'Slub Cotton Tee', 'Cut for a modern, versatile wardrobe, the Slub Cotton Tee moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from cotton blend, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WTE-011', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000034', ARRAY[]::text[], 'Slub Cotton Tee | X-Rare', 'Cut for a modern, versatile wardrobe, the Slub Cotton Tee moves easily from day to night. Tailored through the waist and hip for a fit that reads polished ', now());
