insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('eca6ecae-96ad-4ffc-a320-4d883a083fb9', 'bow-detail-tee-wte016', 'Bow Detail Tee', 'The Bow Detail Tee takes a familiar silhouette and refines it with careful proportions. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from pima cotton, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Layer it into a full look or let it stand on its own; either way it holds its shape. Machine wash cold, hang to dry.', 'XR-WTE-016', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000034', ARRAY[]::text[], 'Bow Detail Tee | X-Rare', 'The Bow Detail Tee takes a familiar silhouette and refines it with careful proportions. A true-to-size cut keeps the silhouette clean and considered, never', now());
