insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('b81cba48-1b30-4dd4-bae0-5b24b7e1312b', 'contrast-trim-tee-wte017', 'Contrast Trim Tee', 'Designed with intention, the Contrast Trim Tee balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from cotton, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-WTE-017', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000034', ARRAY[]::text[], 'Contrast Trim Tee | X-Rare', 'Designed with intention, the Contrast Trim Tee balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, s', now());
