insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('92f3d6c0-ced6-4579-9b86-7e74f038d268', 'signature-logo-tee-wte018', 'Signature Logo Tee', 'A staple built to be worn often, the Signature Logo Tee pairs effortlessly with the rest of your rotation. A true-to-size cut keeps the silhouette clean and considered, never bulky. Made from slub cotton, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Wear it as the foundation of an everyday look or dress it up for something more considered. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WTE-018', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000034', ARRAY['essential']::text[], 'Signature Logo Tee | X-Rare', 'A staple built to be worn often, the Signature Logo Tee pairs effortlessly with the rest of your rotation. A true-to-size cut keeps the silhouette clean an', now());
