insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('7bdc4e82-2ccb-40b9-aae9-cf1d69997e62', 'matching-knit-co-ord-set-wst001', 'Matching Knit Co-Ord Set', 'The Matching Knit Co-Ord Set brings a considered, easy confidence to everyday dressing. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from ribbed knit, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. A dependable piece for regular wear, built to outlast a single season. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WST-001', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000036', ARRAY[]::text[], 'Matching Knit Co-Ord Set | X-Rare', 'The Matching Knit Co-Ord Set brings a considered, easy confidence to everyday dressing. The fit is relaxed through the body without feeling oversized, so i', now());
