insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('4016631f-48af-45fc-976b-5203c11ed6e4', 'ribbed-two-piece-set-wst002', 'Ribbed Two-Piece Set', 'Cut for a modern, versatile wardrobe, the Ribbed Two-Piece Set moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from terry, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WST-002', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000036', ARRAY[]::text[], 'Ribbed Two-Piece Set | X-Rare', 'Cut for a modern, versatile wardrobe, the Ribbed Two-Piece Set moves easily from day to night. Tailored through the waist and hip for a fit that reads poli', now());
