insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('34cc6e45-010e-47db-91bf-0b5f294f13c7', 'utility-two-piece-set-wst004', 'Utility Two-Piece Set', 'The Utility Two-Piece Set takes a familiar silhouette and refines it with careful proportions. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from linen, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Layer it into a full look or let it stand on its own; either way it holds its shape. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WST-004', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000036', ARRAY[]::text[], 'Utility Two-Piece Set | X-Rare', 'The Utility Two-Piece Set takes a familiar silhouette and refines it with careful proportions. Tailored through the waist and hip for a fit that reads poli', now());
