insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('26c743d7-7a6a-48d9-b09c-f57b0990d625', 'printed-two-piece-set-wst008', 'Printed Two-Piece Set', 'Cut for a modern, versatile wardrobe, the Printed Two-Piece Set moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from velour, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. Wear it as the foundation of an everyday look or dress it up for something more considered. Machine wash cold, hang to dry.', 'XR-WST-008', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000036', ARRAY[]::text[], 'Printed Two-Piece Set | X-Rare', 'Cut for a modern, versatile wardrobe, the Printed Two-Piece Set moves easily from day to night. The fit is relaxed through the body without feeling oversiz', now());
