insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('f9777539-50a9-40bf-bf67-cb5e8ae68815', 'velour-lounge-set-wst011', 'Velour Lounge Set', 'Cut for a modern, versatile wardrobe, the Velour Lounge Set moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from ribbed knit, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Wear it as the foundation of an everyday look or dress it up for something more considered. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WST-011', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000036', ARRAY['limited']::text[], 'Velour Lounge Set | X-Rare', 'Cut for a modern, versatile wardrobe, the Velour Lounge Set moves easily from day to night. The fit is relaxed through the body without feeling oversized, ', now());
