insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('49e61fac-7ecd-4089-97fa-00eea1b47209', 'corset-skirt-set-wst012', 'Corset Skirt Set', 'Designed with intention, the Corset Skirt Set balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from terry, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. It''s built for rotation — as comfortable running errands as it is out for the evening. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WST-012', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000036', ARRAY[]::text[], 'Corset Skirt Set | X-Rare', 'Designed with intention, the Corset Skirt Set balances clean lines with real wearability. The fit is relaxed through the body without feeling oversized, so', now());
