insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('6fd367d5-ffd9-4826-b8c3-19a877052087', 'quilted-puffer-jacket-wjk004', 'Quilted Puffer Jacket', 'Cut for a modern, versatile wardrobe, the Quilted Puffer Jacket moves easily from day to night. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from nylon, it holds its shape wash after wash and softens with wear. Clean seaming, a reinforced hem, and minimal branding keep the focus on the cut. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold, hang to dry.', 'XR-WJK-004', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000037', ARRAY['premium']::text[], 'Quilted Puffer Jacket | X-Rare', 'Cut for a modern, versatile wardrobe, the Quilted Puffer Jacket moves easily from day to night. The fit is relaxed through the body without feeling oversiz', now());
