insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('63b2063e-ff06-41fb-9d3f-aaa468ebeb53', 'belted-wool-coat-wjk007', 'Belted Wool Coat', 'Cut for a modern, versatile wardrobe, the Belted Wool Coat moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from denim, it holds its shape wash after wash and softens with wear. Subtle contrast stitching and a tonal interior label round out the construction. Layer it into a full look or let it stand on its own; either way it holds its shape. Hand wash cold and lay flat to dry to keep its finish.', 'XR-WJK-007', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000037', ARRAY['premium']::text[], 'Belted Wool Coat | X-Rare', 'Cut for a modern, versatile wardrobe, the Belted Wool Coat moves easily from day to night. Tailored through the waist and hip for a fit that reads polished', now());
