insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('173cea9f-3f93-4ce5-bd77-9531cc00c178', 'structured-tweed-jacket-wjk009', 'Structured Tweed Jacket', 'A staple built to be worn often, the Structured Tweed Jacket pairs effortlessly with the rest of your rotation. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from wool blend, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. A dependable piece for regular wear, built to outlast a single season. Machine wash cold with like colors; tumble dry low.', 'XR-WJK-009', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000037', ARRAY['premium']::text[], 'Structured Tweed Jacket | X-Rare', 'A staple built to be worn often, the Structured Tweed Jacket pairs effortlessly with the rest of your rotation. Cut with a slightly dropped shoulder and a ', now());
