insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('54dc01aa-4382-4c11-9a14-d34d40ea68e6', 'double-breasted-coat-wjk012', 'Double-Breasted Coat', 'Cut for a modern, versatile wardrobe, the Double-Breasted Coat moves easily from day to night. Tailored through the waist and hip for a fit that reads polished rather than fussy. Made from shearling, it holds its shape wash after wash and softens with wear. Considered hardware and a tonal color palette keep the piece easy to style. Layer it into a full look or let it stand on its own; either way it holds its shape. Machine wash cold with like colors; tumble dry low.', 'XR-WJK-012', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000037', ARRAY['premium','sale']::text[], 'Double-Breasted Coat | X-Rare', 'Cut for a modern, versatile wardrobe, the Double-Breasted Coat moves easily from day to night. Tailored through the waist and hip for a fit that reads poli', now());
