insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('c8fbc1ed-fd59-4bef-9d19-e56b6fa6189a', 'shearling-collar-jacket-wjk013', 'Shearling Collar Jacket', 'Cut for a modern, versatile wardrobe, the Shearling Collar Jacket moves easily from day to night. Cut with a slightly dropped shoulder and a straight body for an easy, unforced fit. Made from denim, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. It''s built for rotation — as comfortable running errands as it is out for the evening. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WJK-013', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000037', ARRAY['premium']::text[], 'Shearling Collar Jacket | X-Rare', 'Cut for a modern, versatile wardrobe, the Shearling Collar Jacket moves easily from day to night. Cut with a slightly dropped shoulder and a straight body ', now());
