insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('02a3f79e-4ae7-41df-9cc3-a0e81d2a1b00', 'track-jogger-pant-wpn011', 'Track Jogger Pant', 'A staple built to be worn often, the Track Jogger Pant pairs effortlessly with the rest of your rotation. An oversized cut through the body gives room to move while keeping the silhouette deliberate, not sloppy. Made from cotton twill, it holds its shape wash after wash and softens with wear. Flat-felled seams and a clean interior finish reflect the attention paid to construction most people never see. A dependable piece for regular wear, built to outlast a single season. Spot clean or dry clean recommended to preserve shape and color.', 'XR-WPN-011', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000038', ARRAY[]::text[], 'Track Jogger Pant | X-Rare', 'A staple built to be worn often, the Track Jogger Pant pairs effortlessly with the rest of your rotation. An oversized cut through the body gives room to m', now());
