insert into products (id, slug, name, description, sku, status, brand_id, category_id, tags, seo_title, seo_description, published_at) values
  ('099daae3-d1b7-41c5-bdfe-6ce9069e7e72', 'wide-leg-culotte-wpn013', 'Wide-Leg Culotte', 'A staple built to be worn often, the Wide-Leg Culotte pairs effortlessly with the rest of your rotation. The fit is relaxed through the body without feeling oversized, so it layers cleanly under outerwear or stands alone. Made from ribbed knit, it holds its shape wash after wash and softens with wear. A reinforced neckline and double-stitched seams are built to handle daily wear. It''s built for rotation — as comfortable running errands as it is out for the evening. Machine wash cold with like colors; tumble dry low.', 'XR-WPN-013', 'active', '9bdd660c-aa2a-41fc-90b0-41aeabaabeb7', '10000000-0000-0000-0000-000000000038', ARRAY['sale']::text[], 'Wide-Leg Culotte | X-Rare', 'A staple built to be worn often, the Wide-Leg Culotte pairs effortlessly with the rest of your rotation. The fit is relaxed through the body without feelin', now());
